 let evs=D.events||[];if(st.f==='tadaa')evs=evs.filter(e=>e.ticketing_mode==='tadaa');if(st.f==='now')evs=evs.filter(e=>e.has_now);if(st.q)evs=evs.filter(e=>(e.title+' '+(e.venue||'')).toLowerCase().includes(st.q.toLowerCase()));
 const events=evs.map(e=>{const pct=e.cap?Math.round(e.sold/e.cap*100):0;const t=sw(e.now_on,'linear-gradient(100deg,#FF3D8B,#FF8A3D)');const pub=e.status==='published';const m=e.metadata||{};
  return {...e,img:e.hero_url||IMG,sub:(e.venue||'Sede por confirmar')+' · '+(e.starts_at?short(e.starts_at):'fecha por confirmar'),mode:e.ticketing_mode==='tadaa'?'TADAA!':'EXTERNA',modeStyle:e.ticketing_mode==='tadaa'?chip('#D6FF35','#08091A'):chip('#EEF1F7','#08091A'),
   media:m.video_url?'Video':'Imagen',tadaa:e.ticketing_mode==='tadaa',external:e.ticketing_mode!=='tadaa',pct:pct+'%',bar:'display: block; width: '+pct+'%; height: 100%; background: #1238FF; transition: width .8s cubic-bezier(.2,.8,.2,1);',
   hasNow:e.has_now,noNow:!e.has_now,nowNA:e.ticketing_mode==='tadaa'?'—':'N/D externa',nowOn:e.now_on,track:t.track.replace('56px','40px').replace('32px','24px'),knob:t.knob.replace(/24px/g,'18px').replace('top: 4px','top: 3px').replace(e.now_on?'28px':'4px',e.now_on?'19px':'3px'),
   toggleNow:async()=>{try{await TV.admin('events/'+e.id+'/now','PATCH',{enabled:!e.now_on});e.now_on=!e.now_on;TV.rerender();TV.toast(e.now_on?'Now! encendido':'Now! en pausa','ok')}catch(err){TV.toast(err.message,'err')}},
   status:pub?'Publicado':'Borrador',statusColor:pub?'#0B7A3B':'#8C93B5',toggleStatus:async()=>{try{await TV.admin('events/'+e.id,'PATCH',{status:pub?'draft':'published'});e.status=pub?'draft':'published';TV.eventsLoaded=false;TV.rerender();TV.toast(pub?'Pasó a borrador':'Publicado','ok')}catch(err){TV.toast(err.message,'err')}}}});
