  primary:async()=>{let ref=null;if(r.status==='delivering'){const v=await TV.modal({title:'Boletos entregados',text:'Folio de la boletera oficial (opcional).',fields:[{name:'ref',label:'Folio externo'}],submit:'Marcar entregado'});if(!v)return;ref=v.ref}try{await TV.admin('orders/'+r.id+'/'+(r.status==='provisional'?'confirm':'deliver'),'POST',{externalReference:ref});TV.toast('Actualizado','ok');adminRefresh()}catch(err){TV.toast(err.message,'err')}},
